  FT["PH-H8499"] = {"id":"PH-H8499","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_10042_2010.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将北苏里高省Dapa - Union - Gen. Luna公路改设为国立二级公路的法案","en":"An Act Converting the Dapa - Union - Gen. Luna Road, Province of Surigao Del Norte Into a National Secondary Road","orig":"An Act Converting the Dapa - Union - Gen. Luna Road, Province of Surigao Del Norte Into a National Secondary Road"},"level":"law","status":"active","topics":["labor"],"docNumber":"Republic Act No. 10042","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-03-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_10042_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8499-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Dapa - Union - Gen. Luna Road, Province of Surigao del Norte is hereby converted into a national secondary road."}},{"id":"PH-H8499-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Public Works and Highways shall issue the necessary rules, orders and circulars to implement the provision of this Act."}},{"id":"PH-H8499-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p121","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Dapa - Union - Gen. Luna Road, Province of Surigao Del Norte Into a National Secondary Road","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H8500"] = {"id":"PH-H8500","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_10043_2010.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立Sibutu市","en":"An Act Establishing a Malaria, Tropical and Infectious Disease Research and Treatment Institute in the Municipality of Sibutu, Province of Tawi-Tawi, Integrating Thereto The Datu Alawaddin Bandon Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Malaria, Tropical and Infectious Disease Research and Treatment Institute in the Municipality of Sibutu, Province of Tawi-Tawi, Integrating Thereto The Datu Alawaddin Bandon Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 10043","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-03-18","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_10043_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8500-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a Malaria, Tropical and Infectious Disease Research and Treatment Institute in the Municipality of Sibutu, Province of Tawi-Tawi, integrating thereto the Datu Alawaddin Bandon Hospital."}},{"id":"PH-H8500-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Institute shall be at par with a secondary hospital with a capacity of at least fifty (50) beds. Aside from the existing facility of the Datu Alawaddin Bandon Hospital, the Institute will be housed in two (2) new buildings; each with a capacity of at least twenty-five (25) beds. The Institute is envisioned to service the Municipality of Sibutu as well as other municipalities of the province."}},{"id":"PH-H8500-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The establishment of the Institute shall be done gradually over a two (2)-year period starting from the approval of this Act with the building of a fifty (50)-bed facility in Barangay Hadji Bidin, Municipality of Sibutu in the first year, and satellite facilities in the other ten (10) municipalities throughout the province in the second year."}},{"id":"PH-H8500-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Institute shall be under the supervision of the Department of Health (DOH), thus it shall be a repository of all data and base for researches on malaria, tropical and infectious diseases."}},{"id":"PH-H8500-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Health shall immediately include in the Department's programs the operationalization of the Malaria, Tropical and Infectious Disease Research and Treatment Institute, the funding of which shall be included in the annual General Appropriations Act.\nThe Autonomous Region in Muslim Mindanao shall continue to provide funds for the operation of the Datu Aiawaddin Bandon Hospital until, its actual integration into the Malaria, Tropical and Infectious Disease Research and Treatment Institute and the funding thereof shall be included in the annual General Appropriations Act."}},{"id":"PH-H8500-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p121"};
  FT["PH-H8501"] = {"id":"PH-H8501","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_10044_2010.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Ozamiz市","en":"An Act Establishing a National High School in Barangay Kinuman Norte, City of Ozamiz, Province of Misamis Occidental to Be Known as Kinuman Norte National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Kinuman Norte, City of Ozamiz, Province of Misamis Occidental to Be Known as Kinuman Norte National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Kinuman Norte, Thành phố Ozamiz, Tỉnh Misamis Occidental được biết đến với tên gọi Trường trung học phổ thông quốc gia Kinuman Norte","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Kinuman Norte, เมือง Ozamiz, จังหวัด Misamis Occidental ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Kinuman Norte","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Kinuman Norte, Kota Ozamiz, Provinsi Misamis Occidental dikenal sebagai Sekolah Menengah Atas Nasional Kinuman Norte","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Kinuman Norte, Bandaraya Ozamiz, Wilayah Misamis Occidental dikenali sebagai Sekolah Menengah Kebangsaan Kinuman Norte"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 10044","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-03-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_10044_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8501-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. - There is hereby established, under the supervision of the Department of Education, a national high school in Barangay Kinuman Norte, City of Ozamiz, Province of Misamis Occidental to be known as Kinuman Norte National High School,"}},{"id":"PH-H8501-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of Kinuman Norte National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8501-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8501-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p121"};
